/* */
void init_app() {
    //clock signal for PA.
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOAEN;
}

void init_gpio(){
    // Activando la señal de reloj:
    RCC->AHB1ENR &= ~RCC_AHB1ENR_GPIOAEN; // Limpiar la posición
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOAEN;  // Activando la señal

    // Configurando el pin A5
    GPIOA->MODER &= ~(0b11 << GPIO_MODER_MODE5_Pos); // Limpiar la posición
    GPIOA->MODER |= (0b01 << GPIO_MODER_MODE5_Pos); // Configurando A5 como salida

    GPIOA->OTYPER &= ~GPIO_OTYPER_OT5; // Limpiando la posición, config push pull

    GPIOA->OSPEEDR &= ~(0b11 << GPIO_OSPEEDR_OSPEED5_Pos); // Limpiar la posición
    GPIOA->OSPEEDR |= (0b01 << GPIO_OSPEEDR_OSPEED5_Pos); // Velocidad media

    GPIOA->PUPDR &= ~(0b11 <<GPIO_PUPDR_PUPD5_Pos); // Limpiar, desactiva las PUPD
    GPIOA->ODR |= (GPIO_ODR_OD5); //

}

// TIMER -----
void init_time3(){
    // Señal de reloj para el timer
    RCC->APB1ENR &= ~(RCC_APB1ENR_TIM3EN); // Limpiar la posición
    RCC->APB1ENR |= RCC_APB1ENR_TIM3EN; // Activar la señal de reloj

    TIM3->CNT = 0; // Reiniciando el contador
    TIM3->PSC = (1600-1); // Divisor por 1600
    TIM3->ARR = (2500-1); // Para generar un evento update cada 0.25 s

    TIM3->CR1 &= ~(0x3 << TIM_CR1_CKD_Pos); // Limpiamos, dejar la señal de reloj complet
    TIM3->CR1 &= ~(TIM_CR1_ARPE); // Limpiamos la posición
    TIM3->CR1 |= (TIM_CR1_ARPE); // Activando el preload para el ARR
    TIM3->CR1 &= ~TIM_CR1_DIR; // Limpiando, contador de forma ascendente

    TIM3->DIER |= TIM_DIER_UIE; // Activando la interrupción

    // Configuramos el NVIC 
    
    // linea 102 stm32f411xe.h
    NVIC_EnableIRQ(TIM3_IRQn); // Registrar la interrupción TIM3 en el NVIC

    TIM3->CR1 |= TIM_CR1_CEN; // Activamos el contador

}

/* Rutina de atencion a la interrupción del TIM3
 * El nombre de esta función se toma del vector de interrupciones definido
 * en el archivo startup_stm32f411xx.s (no modificar este archivo)
*/ 

void TIM3_IRQHandler(void){
    // Verificamos si la bandera está levantada
    if(TIM3->SR && TIM_SR_UIF) {
        TIM3->SR &= ~TIM_SR_UIF; // Limpiando la bandera
        GPIOA->ODR ^= GPIO_ODR_OD5;
    }
}